def test_teardown_request_handler_error(app, client):
    called = []
    app.testing = False

    @app.teardown_request
    def teardown_request1(exc):
        assert type(exc) is ZeroDivisionError
        called.append(True)
        # This raises a new error and blows away sys.exc_info(), so we can
        # test that all teardown_requests get passed the same original
        # exception.
        try:
            raise TypeError()
        except Exception:
            pass

    @app.teardown_request
    def teardown_request2(exc):
        assert type(exc) is ZeroDivisionError
        called.append(True)
        # This raises a new error and blows away sys.exc_info(), so we can
        # test that all teardown_requests get passed the same original
        # exception.
        try:
            raise TypeError()
        except Exception:
            pass

    @app.route("/")
    def fails():
        raise ZeroDivisionError

    rv = client.get("/")
    assert rv.status_code == 500
    assert b"Internal Server Error" in rv.data
    assert len(called) == 2

def test_view_provide_automatic_options_attr_enable(
    app: flask.Flask, client: FlaskClient
) -> None:
    """When default automatic options is disabled in config, it can still be
    enabled by the view class attribute.
    """
    app.config["PROVIDE_AUTOMATIC_OPTIONS"] = False

    class Index(flask.views.View):
        provide_automatic_options = True

        def dispatch_request(self):
            return "Hello World!"

    app.add_url_rule("/", view_func=Index.as_view("index"))
    rv = client.options("/")
    assert rv.allow == {"GET", "HEAD", "OPTIONS"}

def test_provide_automatic_options_method_disable(
    app: flask.Flask, client: FlaskClient
) -> None:
    """Automatic options is ignored if the route handles options."""

    class Index(flask.views.View):
        methods = ["OPTIONS"]

        def dispatch_request(self):
            return "", {"X-Test": "test"}

    app.add_url_rule("/", view_func=Index.as_view("index"))
    rv = client.options()
    assert rv.headers["X-Test"] == "test"
